<?php
declare(strict_types=1);
namespace AIcontrol;
use AIcontrolWorkspaceUi as Ui;

final class SystemsView
{
    private static function form(string $csrf,string $action,int $id,string $label): void
    {
        echo '<form method="post" action="/loader.php?view=systems">'.$csrf.'<input type="hidden" name="action" value="'.$action.'"><input type="hidden" name="system_id" value="'.$id.'"><button class="btn btn-outline-secondary">'.Ui::e($label).'</button></form>';
    }
    public static function render(array $data,string $csrf,array $projects): void
    {
        if(($data['allowed']??true)===false){echo '<p class="alert alert-warning">Systems control requires PIN, password or host-authenticated access.</p>';return;}
        echo '<section class="card mb-3"><div class="card-body"><h2>Linux servers</h2><p>Add a server, install its public key, verify its identity, then assign work. Each server has its own encrypted SSH credential.</p>';
        if(!$data['runner_available'])echo '<p class="alert alert-warning">SSH execution is unavailable on this PHP host. Enable proc_open and install /usr/bin/ssh and /usr/bin/ssh-keyscan on the web host, or run this workspace on a Linux host with those capabilities. Saved systems and scripts remain available.</p>';
        echo '<details id="add-system"><summary>Add a Linux server</summary><form method="post" action="/loader.php?view=systems" class="systems-form">'.$csrf.'<input type="hidden" name="action" value="system_add">';
        foreach([['name','System name','text','120','Web server'],['host','IP address or hostname','text','253','192.0.2.10'],['port','SSH port','number','5','22'],['username','Linux account','text','32','aicontrol']] as [$name,$label,$type,$max,$value])echo '<label class="form-label" for="system-'.$name.'">'.$label.'</label><input class="form-control" id="system-'.$name.'" name="'.$name.'" type="'.$type.'" maxlength="'.$max.'" value="'.($name==='port'||$name==='username'?$value:'').'" placeholder="'.$value.'" required>';
        echo '<label class="form-label" for="system-access">Agent access</label><select class="form-select" id="system-access" name="access"><option value="inspect">Inspection — fixed diagnostic commands</option><option value="maintain">Maintenance — shell commands within the Linux account’s permissions</option></select><p>Setup grants no sudo privileges. Maintenance can change files and services only where this account already has permission.</p><button class="btn btn-primary">Add server and generate setup script</button></form></details>';
        if(!$data['systems'])echo '<p class="mt-3">No Linux servers saved yet.</p>';
        echo '<ul class="systems-list mt-3">';foreach($data['systems'] as $s)echo '<li><a href="/loader.php?view=systems&amp;system='.(int)$s['id'].'">'.Ui::e($s['name']).'</a> · '.Ui::e($s['host']).' · '.(!$s['enabled']?'Disconnected':($s['verified_at']?'Connection tested':'Setup pending')).'</li>';echo '</ul></div></section>';
        $s=$data['selected'];if(!$s)return;$id=(int)$s['id'];
        echo '<section class="card mb-3"><div class="card-body"><h2>'.Ui::e($s['name']).'</h2><p>'.Ui::e($s['username'].'@'.$s['host'].':'.$s['port'].' · '.$s['access']).'</p>';
        if(!$s['enabled']){if(!$s['key_deleted_at']){echo '<p>Credential deletion is unconfirmed. Retry disconnect after checking the private vault.</p>';self::form($csrf,'system_revoke',$id,'Retry disconnect and delete local SSH key');}echo '<p>Disconnected. Local SSH execution is disabled. '.($s['key_deleted_at']?'The local private key was deleted.':'').' Remove the authorized_keys line ending <code>aicontrol-system-'.$id.'</code> on the server to revoke its public key there.</p><details><summary>Delete saved system and task logs</summary><form method="post" action="/loader.php?view=systems" class="systems-form">'.$csrf.'<input type="hidden" name="action" value="system_delete"><input type="hidden" name="system_id" value="'.$id.'"><label class="form-label" for="system-delete-confirm">Type DELETE SYSTEM '.$id.'</label><input id="system-delete-confirm" class="form-control" name="confirmation" required autocomplete="off"><button class="btn btn-outline-danger">Delete saved system and task logs</button></form></details>';}
        else {
            echo '<details'.(!$s['verified_at']?' open':'').'><summary>SSH setup script</summary><p>Run this on the selected server as root or using sudo. It adds the account if missing and preserves existing authorized keys. It prints the server fingerprint for the next step.</p><label class="form-label" for="system-script">Server setup script</label><textarea class="form-control systems-code" id="system-script" readonly rows="12" spellcheck="false">'.Ui::e($data['script']).'</textarea><button type="button" class="btn btn-outline-secondary mt-2" data-copy-report="system-script">Copy setup script</button><span role="status" data-copy-report-status></span></details>';
            echo '<form method="post" action="/loader.php?view=systems" class="systems-form">'.$csrf.'<input type="hidden" name="action" value="system_test"><input type="hidden" name="system_id" value="'.$id.'"><label class="form-label" for="system-fingerprint">Server SHA256 fingerprint</label><input class="form-control" id="system-fingerprint" name="fingerprint" value="'.Ui::e($s['fingerprint']).'" required placeholder="SHA256:…"><button class="btn btn-outline-primary">Verify identity and test SSH</button></form>';
            if($s['verified_at'])echo '<p>Last successful check: '.Ui::e(Ui::time(gmdate('c',(int)$s['verified_at']))).'. Each SSH connection checks the pinned server key.</p>';
            if($s['error'])echo '<p class="alert alert-warning">'.Ui::e($s['error']).'</p>';
            if($s['facts'])echo '<details><summary>Last observed system information</summary><pre class="systems-code">'.Ui::e($s['facts']).'</pre></details>';
            if($s['verified_at']){
                echo '<form method="post" action="/loader.php?view=systems" class="systems-form">'.$csrf.'<input type="hidden" name="action" value="system_start"><input type="hidden" name="system_id" value="'.$id.'"><label class="form-label" for="system-project">Related task project (optional)</label><select class="form-select" id="system-project" name="project_id"><option value="">System task only</option>';foreach($projects as $p)echo '<option value="'.(int)$p['id'].'">'.Ui::e($p['name']).'</option>';echo '</select><label class="form-label" for="system-task">Task for the Linux agent</label><textarea class="form-control" id="system-task" name="task" rows="3" maxlength="4000" placeholder="Inspect disk usage and explain what needs attention." required></textarea><p>Up to eight model decisions; one remote command per decision. Start, then advance steps or enable automatic steps while this page stays open.</p><button class="btn btn-primary">Start system task</button></form>';
            }
            self::form($csrf,'system_revoke',$id,'Disconnect and delete local SSH key');
        }
        echo '</div></section>';
        if($data['runs']){echo '<section class="card mb-3"><div class="card-body"><h2>System task history</h2><ul class="systems-list">';foreach($data['runs'] as $r)echo '<li><a href="/loader.php?view=systems&amp;system='.$id.'&amp;system_run='.(int)$r['id'].'">#'.(int)$r['id'].' · '.Ui::e($r['task']).'</a> · '.Ui::e($r['status']).'</li>';echo '</ul></div></section>';}
        $r=$data['run'];if(!$r)return;
        echo '<section class="card"><div class="card-body" data-system-run="'.(int)$r['id'].'" data-system-status="'.Ui::e($r['status']).'"><h2>Task #'.(int)$r['id'].'</h2><p>'.Ui::e($r['task']).'</p><p role="status">'.Ui::e($r['status']).' · '.(int)$r['rounds'].' / 8 decisions</p>';
        foreach(['system_step'=>'Run next agent step','system_stop'=>'Stop system task'] as $action=>$label)if(in_array($r['status'],['ready','working'],true))echo '<form method="post" action="/loader.php?view=systems" data-system-action="'.$action.'">'.$csrf.'<input type="hidden" name="action" value="'.$action.'"><input type="hidden" name="system_id" value="'.$id.'"><input type="hidden" name="run_id" value="'.(int)$r['id'].'"><button class="btn '.($action==='system_stop'?'btn-outline-danger':'btn-primary').'"'.($action==='system_step'&&$r['status']!=='ready'?' disabled':'').'>'.$label.'</button></form>';
        if($r['status']==='ready')echo '<button type="button" class="btn btn-outline-secondary mt-2" data-system-auto>Run automatic steps</button>';
        if($r['status']==='working')echo '<p>Progress is unverified after this page reload. Stop the task before starting another; no command will be retried automatically.</p>';
        if($r['error'])echo '<p class="alert alert-warning">'.Ui::e($r['error']).'</p>';
        if($r['result'])echo '<pre class="systems-code">'.Ui::e($r['result']).'</pre>';
        $report=['format'=>'AIcontrol systems execution v1','generated_utc'=>gmdate('c'),'system'=>['id'=>$id,'name'=>$s['name'],'host'=>$s['host'],'port'=>$s['port'],'username'=>$s['username'],'access'=>$s['access'],'fingerprint'=>$s['fingerprint']],'run'=>$r,'commands'=>$data['commands'],'agent_decisions_and_provider_metadata'=>$data['messages']];
        echo '<label class="form-label" for="system-report">Commands, stdout, stderr, exit codes and timing</label><textarea id="system-report" class="form-control systems-code" readonly rows="14">'.Ui::e(json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE)).'</textarea><button class="btn btn-outline-secondary mt-2" type="button" data-copy-report="system-report">Copy diagnostic report</button><span role="status" data-copy-report-status></span><button class="btn btn-outline-secondary mt-2" type="button" data-system-download>Download report JSON</button><p>Outputs are capped at 16 KB per stream per command; truncation and timeouts are recorded. Review reports for private server content before sharing. Stop ends local SSH and prevents further commands; an interrupted remote command can have an uncertain outcome.</p><noscript><p>Setup, connection checks, manual steps, Stop and the report remain available without JavaScript.</p></noscript></div></section>';
    }
}
